import { withAuth } from "@workos-inc/authkit-nextjs";
import type { User as WorkOSUser } from "@workos-inc/node";

export type User = {
  id: string;
  email: string;
  name: string;
  createdAt: string;
};

const users: User[] = [
  { id: "1", email: "ada@example.com", name: "Ada", createdAt: "2026-01-04" },
  { id: "2", email: "grace@example.com", name: "Grace", createdAt: "2026-02-11" },
];

export async function listUsers(): Promise<User[]> {
  return users;
}

export async function getUser(id: string): Promise<User | undefined> {
  return users.find((u) => u.id === id);
}

// WorkOS is the source of truth for identity (email/password + Google sign-in,
// session handling). This mirrors each authenticated WorkOS user into the
// local user store on first sight, keyed by their stable WorkOS user id, so
// the rest of the app (dashboard, team list, etc.) keeps working against the
// plain `User` shape it already knows.
function syncUserFromWorkOS(workosUser: WorkOSUser): User {
  const existing = users.find((u) => u.id === workosUser.id);
  if (existing) {
    existing.email = workosUser.email;
    existing.name = displayName(workosUser);
    return existing;
  }

  const user: User = {
    id: workosUser.id,
    email: workosUser.email,
    name: displayName(workosUser),
    createdAt: workosUser.createdAt.slice(0, 10),
  };
  users.push(user);
  return user;
}

function displayName(workosUser: WorkOSUser): string {
  if (workosUser.name) return workosUser.name;
  const parts = [workosUser.firstName, workosUser.lastName].filter(Boolean);
  return parts.length > 0 ? parts.join(" ") : workosUser.email;
}

// Reads the signed-in user from the AuthKit session (set via email+password
// or Google sign-in) and syncs it into the local user store. Returns
// undefined when nobody is signed in.
export async function getCurrentUser(): Promise<User | undefined> {
  const { user } = await withAuth();
  if (!user) return undefined;
  return syncUserFromWorkOS(user);
}

